import {ShieldCheckIcon} from '@primer/octicons-react'
import {AlertResolution, type AlertEvent} from '../../../types/alerts'
import {TimelineEventWithActor} from './shared'
import styles from './ClosedEvent.module.css'

interface ClosedEventProps {
  event: AlertEvent
  alertResolution: AlertResolution
}

function getClosedActionText(resolution: AlertResolution): string {
  if (resolution === AlertResolution.Outdated) {
    return 'closed as outdated'
  }
  if (resolution === AlertResolution.ExceptionAdded || resolution === AlertResolution.LicensesAdded) {
    return 'closed as amendment'
  }
  return 'closed this alert'
}

export function ClosedEvent({event, alertResolution}: ClosedEventProps) {
  return (
    <TimelineEventWithActor
      event={event}
      icon={<ShieldCheckIcon size={16} />}
      badgeClassName="bgColor-done-emphasis fgColor-onEmphasis"
      actionText={getClosedActionText(alertResolution)}
      itemClassName={styles.closedEventItem}
      data-testid="timeline-event-closed"
    />
  )
}
