import {XIcon, NoteIcon} from '@primer/octicons-react'
import {Stack} from '@primer/react'
import type {AlertEvent} from '../../../types/alerts'
import {TimelineEventWithActor, getEventComment} from './shared'

interface ReviewDeniedEventProps {
  event: AlertEvent
}

export function ReviewDeniedEvent({event}: ReviewDeniedEventProps) {
  const comment = getEventComment(event.eventBody)

  return (
    <TimelineEventWithActor
      event={event}
      icon={<XIcon size={16} />}
      actionText="denied closure request"
      data-testid="timeline-event-review-denied"
    >
      {/* Show comment if present */}
      {comment && (
        <Stack direction="horizontal" align="center" gap="condensed" className="mt-1">
          <NoteIcon size={16} className="fgColor-muted" />
          <span className="f6 color-fg-muted">{comment}</span>
        </Stack>
      )}
    </TimelineEventWithActor>
  )
}
