import {Stack, Text} from '@primer/react'
import {PackageIcon} from '@primer/octicons-react'
import {clsx} from 'clsx'
import styles from './LicenseComplianceAlertDescription.module.css'
import type {Alert} from '../types/alerts'

export interface LicenseComplianceAlertDescriptionProps {
  license: Alert['license']
  packageEcosystem: Alert['packageEcosystem']
  packageName: Alert['packageName']
  packageVersion: Alert['packageVersion']
}

export function LicenseComplianceAlertDescription({
  license,
  packageEcosystem,
  packageName,
  packageVersion,
}: LicenseComplianceAlertDescriptionProps) {
  const renderPackageInfo = () => (
    <Stack
      direction="horizontal"
      align="center"
      gap="spacious"
      className={clsx(styles.packageContainer, 'border rounded-top-2 bgColor-inset')}
    >
      <Stack direction="vertical" gap="condensed" className={styles.packageName}>
        <Text as="span" size="small" className="f6-light fgColor-muted">
          Package
        </Text>
        <Stack direction="horizontal" align="center" gap="condensed">
          <PackageIcon size={16} className={styles.packageIcon} />
          <span>
            <span className="text-bold">{packageName}</span> ({packageEcosystem})
          </span>
        </Stack>
      </Stack>
      <Stack direction="vertical" gap="condensed" className={styles.packageVersion}>
        <Text as="span" size="small" className="f6-light fgColor-muted">
          Version
        </Text>
        <span className="text-mono">{packageVersion}</span>
      </Stack>
    </Stack>
  )

  const renderLicenseInfo = () => (
    <div className={clsx(styles.licenseContainer, 'border rounded-bottom-2 border-top-0')}>
      {license ? (
        <>
          Detected expression <span className="text-mono">{license}</span> which has not been allowed by your license
          policy.
        </>
      ) : (
        <>No license detected</>
      )}
    </div>
  )

  return (
    <Stack className="tmp-mb-3" data-testid="license-compliance-alert-description" direction="vertical" gap="none">
      {renderPackageInfo()}
      {renderLicenseInfo()}
    </Stack>
  )
}
