import {CommentIcon, NoteIcon, GitPullRequestIcon} from '@primer/octicons-react'
import {Stack, Link, Button} from '@primer/react'
import type {AlertEvent, ReviewEventBody} from '../../../types/alerts'
import {TimelineEventWithActor, parseEventBody, getEventComment} from './shared'

interface ReviewRequestedEventProps {
  event: AlertEvent
  onReviewRequest?: () => void
}

export function ReviewRequestedEvent({event, onReviewRequest}: ReviewRequestedEventProps) {
  const reviewInfo = parseEventBody<ReviewEventBody>(event.eventBody)
  const comment = getEventComment(event.eventBody)

  // Custom action text for review_requested with comment reason
  const actionText = comment ? 'requested to close as exception' : 'requested to close'

  return (
    <TimelineEventWithActor
      event={event}
      icon={<CommentIcon size={16} />}
      actionText={actionText}
      data-testid="timeline-event-review-requested"
    >
      {/* Show PR info for review_requested events */}
      {reviewInfo?.pull_request_number != null && reviewInfo?.pull_request_title && (
        <Stack direction="horizontal" align="center" justify="space-between" className="mt-1">
          <Stack direction="horizontal" align="center" gap="condensed">
            <GitPullRequestIcon size={16} className="color-fg-success" />
            <Link href={`../../pull/${reviewInfo.pull_request_number}`} muted className="f6">
              {reviewInfo.pull_request_title} #{reviewInfo.pull_request_number}
            </Link>
          </Stack>
          {onReviewRequest && (
            <Button
              variant="primary"
              size="small"
              onClick={onReviewRequest}
              data-testid="review-workflow-modal-timeline-button"
            >
              Review request
            </Button>
          )}
        </Stack>
      )}

      {/* Show comment if present */}
      {comment && (
        <Stack direction="horizontal" align="center" gap="condensed" className="mt-1">
          <NoteIcon size={16} className="fgColor-muted" />
          <span className="f6 color-fg-muted">{comment}</span>
        </Stack>
      )}
    </TimelineEventWithActor>
  )
}
