import {ActionList, ActionMenu, FormControl, Stack, TextInput, Text} from '@primer/react'
import type {Alert} from '../../types/alerts'
import {PolicyLevel} from '../../types/policies'
import {getSpdxSummary} from '../../helpers/spdx'
import styles from './PolicyUpdateForm.module.css'
import {AMENDMENT_PACKAGE, AMENDMENT_LICENSE, AMENDMENT_PACKAGE_WILDCARD} from './constants'
import {Fragment} from 'react'
import {useRouteQuery} from '@github-ui/react-core/future/use-route-query'
import {licenseComplianceAlertRoute} from '../../routes/license-compliance-alert-route'

interface ActionMenuItem {
  value: string
  label: string
  description?: string
  showDivider?: boolean
  disabled?: boolean
}

interface PolicySection {
  title: string
  description: string
  selectedItem: string
  onSelect: (value: string) => void
  items: ActionMenuItem[]
}

interface PolicyUpdateFormProps {
  alert: Alert
  owner: string
  repo: string
  amendment: string
  onAmendmentChange: (value: string) => void
  scope: string
  onScopeChange: (value: string) => void
  wildcardPattern: string
  onWildcardChange: (event: React.ChangeEvent<HTMLInputElement>) => void
  wildcardValidationError: string
}

export function PolicyUpdateForm({
  alert,
  owner,
  repo,
  amendment,
  onAmendmentChange,
  scope,
  onScopeChange,
  wildcardPattern,
  onWildcardChange,
  wildcardValidationError,
}: PolicyUpdateFormProps) {
  const {
    data: {enterpriseName},
  } = useRouteQuery(licenseComplianceAlertRoute, 'mainQuery')

  const spdxSummary = getSpdxSummary(alert.license)

  const sections: PolicySection[] = [
    {
      title: 'Updates',
      description: 'Choose what to add to the license policy',
      selectedItem: amendment,
      onSelect: onAmendmentChange,
      items: [
        {
          value: AMENDMENT_PACKAGE,
          label: alert.packageName,
          description: 'Add package to exceptions list',
        },
        {
          value: AMENDMENT_PACKAGE_WILDCARD,
          label: 'Wildcard pattern',
          description: 'Add matching packages to exceptions list',
        },
        {
          value: AMENDMENT_LICENSE,
          label: spdxSummary.label,
          description: spdxSummary.description,
          showDivider: true,
          disabled: !alert.license,
        },
      ],
    },
    {
      title: 'Scope',
      description: 'Choose where to apply the updates',
      selectedItem: scope,
      onSelect: onScopeChange,
      items: [
        {
          value: PolicyLevel.Repository,
          label: 'This repository',
          description: `${owner}/${repo}`,
        },
        {
          value: PolicyLevel.Enterprise,
          label: 'Enterprise policy',
          description: `All repositories in ${enterpriseName || 'the enterprise'}`,
        },
      ],
    },
  ]

  const renderActionMenu = (section: PolicySection) => (
    <ActionMenu>
      <ActionMenu.Button>
        {section.items.find(item => item.value === section.selectedItem)?.label || 'Select an option'}
      </ActionMenu.Button>
      <ActionMenu.Overlay>
        <ActionList selectionVariant="single" role="menu" aria-label="Policy update options">
          {section.items.map(item => (
            <Fragment key={item.label}>
              {item.showDivider && <ActionList.Divider />}
              <ActionList.Item
                selected={item.value === section.selectedItem}
                role="menuitemradio"
                aria-checked={item.value === section.selectedItem}
                onSelect={() => section.onSelect(item.value)}
                disabled={item.disabled}
              >
                {item.label}
                <ActionList.Description className={item.disabled ? 'fgColor-attention' : undefined} variant="block">
                  {item.description}
                </ActionList.Description>
              </ActionList.Item>
            </Fragment>
          ))}
        </ActionList>
      </ActionMenu.Overlay>
    </ActionMenu>
  )

  const renderPatternInput = () => (
    <FormControl className="flex-self-stretch">
      <FormControl.Label visuallyHidden>Package name pattern</FormControl.Label>
      <TextInput
        block
        monospace
        value={wildcardPattern}
        onChange={onWildcardChange}
        placeholder={`Enter pattern for ${alert.packageName}`}
        validationStatus={wildcardValidationError ? 'error' : undefined}
      />
      <FormControl.Caption>
        Can only contain one * character and must match current package.
        <br />
        Example: <span className="text-mono fgColor-default">octo-package/*</span>,{' '}
        <span className="text-mono fgColor-default">octo-package*</span>
      </FormControl.Caption>
      {wildcardValidationError && (
        <FormControl.Validation variant="error">{wildcardValidationError}</FormControl.Validation>
      )}
    </FormControl>
  )

  return (
    <Stack direction="vertical" gap="spacious">
      {sections.map(section => (
        <Stack key={section.title} align="start" gap="condensed">
          <Text className={styles.contentTitle} weight="semibold">
            {section.title} *
          </Text>
          {renderActionMenu(section)}
          <Text className="fgColor-muted" size="small">
            {section.description}
          </Text>
          {section.selectedItem === AMENDMENT_PACKAGE_WILDCARD && renderPatternInput()}
        </Stack>
      ))}
    </Stack>
  )
}
