import {reactFetchJSON} from '@github-ui/verified-fetch'
import type {PolicyLevel, PackageAction} from '../types/policies'

const REQUEST_DISMISSAL_OPERATION = 'request_dismissal'
const CREATE_PACKAGE_EXCEPTION_OPERATION = 'create_exception'
const ADD_LICENSES_FOR_ALERT_OPERATION = 'add_licenses_for_alert'
const DENY_DISMISSAL_OPERATION = 'deny_dismissal'

function getUpdateAlertRoute(owner: string, repo: string, number: string) {
  return `/${owner}/${repo}/security/license-compliance/${number}`
}

async function updateAlert(
  owner: string,
  repo: string,
  number: string,
  operation: string,
  additionalBody?: Record<string, string>,
) {
  const updateAlertRoute = getUpdateAlertRoute(owner, repo, number)

  const response = await reactFetchJSON(updateAlertRoute, {
    method: 'PUT',
    body: {operation, ...additionalBody},
  })

  const data = await response.json()

  if (!response.ok) {
    throw new Error(data.error || response.statusText)
  }

  return data
}

export async function requestAlertDismissal(owner: string, repo: string, number: string) {
  return updateAlert(owner, repo, number, REQUEST_DISMISSAL_OPERATION)
}

export async function requestAlertDismissalWithComment(
  owner: string,
  repo: string,
  number: string,
  reason: string,
  comment: string,
) {
  return updateAlert(owner, repo, number, REQUEST_DISMISSAL_OPERATION, {
    reason,
    comment,
  })
}

export async function createPackageException(
  owner: string,
  repo: string,
  number: string,
  comment: string,
  policyLevel: PolicyLevel,
  packageAction: PackageAction,
  pattern: string,
) {
  return updateAlert(owner, repo, number, CREATE_PACKAGE_EXCEPTION_OPERATION, {
    comment,
    policy_level: policyLevel,
    package_action: packageAction,
    pattern,
  })
}

export async function addLicensesForAlert(
  owner: string,
  repo: string,
  number: string,
  comment: string,
  policyLevel: PolicyLevel,
) {
  return updateAlert(owner, repo, number, ADD_LICENSES_FOR_ALERT_OPERATION, {comment, policy_level: policyLevel})
}

export async function denyAlertDismissal(owner: string, repo: string, number: string, comment: string) {
  return updateAlert(owner, repo, number, DENY_DISMISSAL_OPERATION, {comment})
}
