import {
  useAddLicensesForAlertMutation,
  useCreatePackageExceptionMutation,
  useDenyRequestMutation,
} from '../../hooks/use-alert-update-mutation'

interface UseReviewWorkflowMutationsProps {
  owner: string
  repo: string
  alertNumber: string
  onError: (error: string) => void
  onSettled: () => void
}

export const useReviewWorkflowMutations = ({
  owner,
  repo,
  alertNumber,
  onError,
  onSettled,
}: UseReviewWorkflowMutationsProps) => {
  const mutationCommonProps = {
    owner,
    repo,
    number: alertNumber,
    onError,
    onSettled,
  }

  const createExceptionMutation = useCreatePackageExceptionMutation(mutationCommonProps)
  const addLicensesForAlertMutation = useAddLicensesForAlertMutation(mutationCommonProps)
  const denyRequestMutation = useDenyRequestMutation(mutationCommonProps)

  const isLoading =
    createExceptionMutation.isPending || addLicensesForAlertMutation.isPending || denyRequestMutation.isPending

  return {
    createExceptionMutation,
    addLicensesForAlertMutation,
    denyRequestMutation,
    isLoading,
  }
}
